<?php
require_once dirname(__DIR__).'/includes/auth.php';require_role('administrator');$temporary=null;$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['user_id']??0);$q=db()->prepare('SELECT id,email FROM users WHERE id=?');$q->execute([$id]);$target=$q->fetch();if(!$target)$err='Select a valid account.';else{$temporary=bin2hex(random_bytes(8)).'aA1!';db()->prepare('UPDATE users SET password_hash=?,must_change_password=1 WHERE id=?')->execute([password_hash($temporary,PASSWORD_DEFAULT),$id]);audit('password_reset','user',$id,'Administrator reset password; user must change it');$pageTarget=$target;}}$users=db()->query('SELECT id,first_name,last_name,email FROM users ORDER BY last_name')->fetchAll();$pageTitle='Reset account password';require dirname(__DIR__).'/includes/header.php';
?><p class="page-intro">Generate a one-time temporary password. Deliver it to the account holder through an appropriate private channel.</p><?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?><?php if($temporary): ?><div class="alert alert-warning"><strong>Temporary password for <?= e($pageTarget['email']) ?> (shown once):</strong> <code><?= e($temporary) ?></code></div><?php endif; ?><form method="post" class="card p-4"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label class="form-label">Account</label><select class="form-select mb-3" name="user_id" required><?php foreach($users as $person): ?><option value="<?= (int)$person['id'] ?>"><?= e($person['last_name'].', '.$person['first_name'].' · '.$person['email']) ?></option><?php endforeach; ?></select><button class="btn btn-warning" data-confirm="Reset this account's password?">Reset and generate temporary password</button></form><?php require dirname(__DIR__).'/includes/footer.php'; ?>
